#include <QtCore>
#include <QtNetwork>
#include <cstdio>
#include <fcntl.h>
#include <io.h>
#include "halab_tools.h"
static bool readExact(char *data,size_t count){size_t done=0;while(done<count){size_t n=fread(data+done,1,count-done,stdin);if(!n)return false;done+=n;}return true;}
static void send(QJsonObject object){auto payload=QJsonDocument(object).toJson(QJsonDocument::Compact);quint32 n=quint32(payload.size());char header[4]={char(n),char(n>>8),char(n>>16),char(n>>24)};fwrite(header,1,4,stdout);fwrite(payload.data(),1,payload.size(),stdout);fflush(stdout);}
static QJsonObject handoff(QJsonObject request){
 QTcpSocket socket;QString token;
 auto connectDesktop=[&]{socket.abort();QFile file(HalabTools::profile()+"/connector.json");if(!file.open(QIODevice::ReadOnly))return false;auto config=QJsonDocument::fromJson(file.readAll()).object();int port=config["port"].toInt();token=config["token"].toString();if(port<1||port>65535||token.size()!=64)return false;socket.connectToHost(QHostAddress::LocalHost,quint16(port));return socket.waitForConnected(300);};
 if(!connectDesktop()){QProcess launcher;HalabTools::hidden(launcher);launcher.setProgram(QCoreApplication::applicationDirPath()+"/HalabDownloadManager.exe");launcher.setArguments({"--listen"});if(!launcher.startDetached())return {{"ok",false},{"error","Could not launch Halab Download Manager"}};bool connected=false;for(int i=0;i<30;++i){if(connectDesktop()){connected=true;break;}QThread::msleep(150);}if(!connected)return {{"ok",false},{"error","Desktop connector did not respond"}};}
 request["_token"]=token;socket.write(QJsonDocument(request).toJson(QJsonDocument::Compact)+"\n");if(socket.bytesToWrite()&&!socket.waitForBytesWritten(2000))return {{"ok",false},{"error","Could not send desktop request"}};QByteArray response;QElapsedTimer timer;timer.start();while(timer.elapsed()<5000&&!response.contains('\n')){if(socket.waitForReadyRead(500))response+=socket.readAll();if(response.size()>65536)break;}auto result=QJsonDocument::fromJson(response.trimmed()).object();if(result.isEmpty())return {{"ok",false},{"error","Desktop did not acknowledge request"}};return result;
}
static QJsonObject formats(QString url){
 QString engine=HalabTools::tool("yt-dlp");if(engine.isEmpty())return {{"ok",false},{"error","Video engine is not installed"}};
 QProcess p;HalabTools::hidden(p);auto args=HalabTools::baseArgs();args<<"--dump-single-json"<<"--skip-download"<<"--"<<url;p.start(engine,args);if(!p.waitForStarted(5000))return {{"ok",false},{"error","Video engine could not start"}};
 QByteArray data,errors;QElapsedTimer timer;timer.start();while(p.state()!=QProcess::NotRunning&&timer.elapsed()<60000){p.waitForReadyRead(300);data+=p.readAllStandardOutput();errors+=p.readAllStandardError();if(data.size()>16*1024*1024){p.kill();p.waitForFinished(3000);return {{"ok",false},{"error","Video metadata exceeds limit"}};}}if(p.state()!=QProcess::NotRunning){p.kill();p.waitForFinished(3000);return {{"ok",false},{"error","Video lookup timed out"}};}data+=p.readAllStandardOutput();errors+=p.readAllStandardError();if(p.exitCode()!=0)return {{"ok",false},{"error",QString::fromUtf8(errors.right(1500))}};
 auto info=QJsonDocument::fromJson(data).object();QJsonArray input=info["formats"].toArray(),out;if(input.isEmpty()&&info.contains("url"))input.append(info);bool ffmpeg=!HalabTools::ffmpegDir().isEmpty();
 for(auto item:input){auto f=item.toObject();QString id=f["format_id"].toString("best"),video=f["vcodec"].toString(),audio=f["acodec"].toString();if(f["has_drm"].toBool()||f["ext"]=="mhtml")continue;if(!QRegularExpression("^[A-Za-z0-9_.-]{1,80}$").match(id).hasMatch())continue;bool merge=!video.isEmpty()&&video!="none"&&audio=="none";out.append(QJsonObject{{"id",id},{"ext",f["ext"]},{"height",f["height"]},{"fps",f["fps"]},{"audioOnly",video=="none"},{"needsMerge",merge},{"available",!merge||ffmpeg},{"note",f["format_note"]}});if(out.size()>=250)break;}
 return {{"ok",!out.isEmpty()},{"title",info["title"]},{"formats",out},{"ffmpeg",ffmpeg},{"error",out.isEmpty()?"No downloadable public formats were found":""}};
}
int main(int argc,char**argv){QCoreApplication app(argc,argv);app.setOrganizationName("Mahmud Abbas");app.setApplicationName("HalabDownloadManager");_setmode(_fileno(stdin),_O_BINARY);_setmode(_fileno(stdout),_O_BINARY);
 if(app.arguments().size()>1&&app.arguments()[1].startsWith("chrome-extension://")){QFile manifest(QCoreApplication::applicationDirPath()+"/com.mahmudabbas.halab.json");if(!manifest.open(QIODevice::ReadOnly))return 2;auto allowed=QJsonDocument::fromJson(manifest.readAll()).object()["allowed_origins"].toArray();if(!allowed.contains(app.arguments()[1]))return 3;}
 char header[4];if(!readExact(header,4))return 0;quint32 n=quint8(header[0])|(quint32(quint8(header[1]))<<8)|(quint32(quint8(header[2]))<<16)|(quint32(quint8(header[3]))<<24);if(n>65536||!n){send({{"ok",false},{"error","Invalid message size"}});return 1;}QByteArray payload(n,0);if(!readExact(payload.data(),n))return 1;auto request=QJsonDocument::fromJson(payload).object();QString op=request["op"].toString();
 if(op=="ping"){send({{"ok",true},{"name","Halab Download Manager"},{"copyright","Copyright (c) 2026 Mahmud Abbas"},{"version","1.0.3"}});return 0;}
 if(!HalabTools::validUrl(request["url"].toString())){send({{"ok",false},{"error","Only HTTP and HTTPS URLs are supported"}});return 0;}
 if(op=="formats")send(formats(request["url"].toString()));else if(op=="download"||op=="video"){request["name"]=request["name"].toString().left(200);request["title"]=request["title"].toString().left(200);if(op=="video"&&!QRegularExpression("^[A-Za-z0-9_.-]{1,80}$").match(request["formatId"].toString()).hasMatch()){send({{"ok",false},{"error","Invalid video format"}});return 0;}send(handoff(request));}else send({{"ok",false},{"error","Unsupported operation"}});return 0;}
